package com.afkbloodrchelper;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(AfkBloodRcHelperConfig.GROUP)
public interface AfkBloodRcHelperConfig extends Config
{
	String GROUP = "afkbloodrchelper";

	@ConfigSection(
		name = "Highlight Next Action",
		description = "Highlight the next thing to click.",
		position = 10
	)
	String sectionAction = "action";

	@ConfigSection(
		name = "Idle Screen Tint",
		description = "Tint the whole screen when idle.",
		position = 20
	)
	String sectionIdleTint = "idleTint";

	@ConfigSection(
		name = "Active Screen Tint",
		description = "Tint the whole screen when active.",
		position = 30,
		closedByDefault = true
	)
	String sectionActiveTint = "activeTint";

	// ---- General ----

	@ConfigItem(
		keyName = "showInfoPanel",
		name = "Show Info Panel",
		description = "Show the info panel with the current blood runecrafting stage.",
		position = 0
	)
	default boolean showInfoPanel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "suggestRun",
		name = "Suggest Enabling Run",
		description = "Highlight the run orb when run is off and energy is over 50%.",
		position = 1
	)
	default boolean suggestRun()
	{
		return true;
	}

	@ConfigItem(
		keyName = "remindBloodEssence",
		name = "Remind Blood Essence",
		description = "Highlight an inactive blood essence when you aren't carrying an active one.",
		position = 2
	)
	default boolean remindBloodEssence()
	{
		return true;
	}

	@ConfigItem(
		keyName = "stepCloserToBloodAltar",
		name = "Step Closer to Blood Altar",
		description = "After venerating the second load, step a few tiles south of the Dark Altar and click the Blood Altar from there instead of walking.",
		position = 3
	)
	default boolean stepCloserToBloodAltar()
	{
		return false;
	}

	@ConfigItem(
		keyName = "notifyAction",
		name = "Notify When Action Needed",
		description = "Send a notification when you need to do something (once each time you go from busy to needing to act).",
		position = 5
	)
	default Notification notifyAction()
	{
		return Notification.OFF;
	}

	@Range(min = 0, max = 5000)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "idleDelay",
		name = "Idle Delay",
		description = "How long the player must stand still before being considered idle.",
		position = 4
	)
	default int idleDelay()
	{
		return 600;
	}

	// ---- Highlight ----

	@ConfigItem(
		keyName = "actionEnabled",
		name = "Enabled",
		description = "Highlight the next thing to click.",
		section = sectionAction,
		position = 1
	)
	default boolean actionEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "actionOnlyWhenIdle",
		name = "Only When Idle",
		description = "Only show the highlight while the player is idle.",
		section = sectionAction,
		position = 2
	)
	default boolean actionOnlyWhenIdle()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pathDisplay",
		name = "Path Display",
		description = "Where to draw the walking path to the next destination.",
		section = sectionAction,
		position = 3
	)
	default PathDisplay pathDisplay()
	{
		return PathDisplay.FLOOR_AND_MINIMAP;
	}

	@Alpha
	@ConfigItem(
		keyName = "pathColor",
		name = "Path Color",
		description = "Color of the path line.",
		section = sectionAction,
		position = 4
	)
	default Color pathColor()
	{
		return new Color(0, 200, 255, 200);
	}

	@Alpha
	@ConfigItem(
		keyName = "actionColor",
		name = "Color",
		description = "Highlight color.",
		section = sectionAction,
		position = 5
	)
	default Color actionColor()
	{
		return new Color(255, 255, 0, 128);
	}

	@ConfigItem(
		keyName = "actionFlash",
		name = "Flashing",
		description = "Flash between two colors.",
		section = sectionAction,
		position = 6
	)
	default boolean actionFlash()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "actionColor2",
		name = "Color 2",
		description = "Second color used when flashing.",
		section = sectionAction,
		position = 7
	)
	default Color actionColor2()
	{
		return new Color(0, 255, 255, 128);
	}

	@Range(min = 1)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "actionColor1Time",
		name = "Color 1 Time",
		description = "Milliseconds to show color 1 when flashing.",
		section = sectionAction,
		position = 8
	)
	default int actionColor1Time()
	{
		return 500;
	}

	@Range(min = 1)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "actionColor2Time",
		name = "Color 2 Time",
		description = "Milliseconds to show color 2 when flashing.",
		section = sectionAction,
		position = 9
	)
	default int actionColor2Time()
	{
		return 500;
	}

	// ---- Idle tint ----

	@ConfigItem(
		keyName = "idleTint",
		name = "Enabled",
		description = "Tint the whole screen when idle.",
		section = sectionIdleTint,
		position = 1
	)
	default boolean idleTint()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "idleTintColor",
		name = "Color",
		description = "Tint color.",
		section = sectionIdleTint,
		position = 2
	)
	default Color idleTintColor()
	{
		return new Color(255, 175, 175, 64);
	}

	@ConfigItem(
		keyName = "idleTintFlash",
		name = "Flashing",
		description = "Flash between two colors.",
		section = sectionIdleTint,
		position = 3
	)
	default boolean idleTintFlash()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "idleTintColor2",
		name = "Color 2",
		description = "Second color used when flashing.",
		section = sectionIdleTint,
		position = 4
	)
	default Color idleTintColor2()
	{
		return new Color(0, 0, 0, 64);
	}

	@Range(min = 1)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "idleTintColor1Time",
		name = "Color 1 Time",
		description = "Milliseconds to show color 1 when flashing.",
		section = sectionIdleTint,
		position = 5
	)
	default int idleTintColor1Time()
	{
		return 600;
	}

	@Range(min = 1)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "idleTintColor2Time",
		name = "Color 2 Time",
		description = "Milliseconds to show color 2 when flashing.",
		section = sectionIdleTint,
		position = 6
	)
	default int idleTintColor2Time()
	{
		return 600;
	}

	// ---- Active tint ----

	@ConfigItem(
		keyName = "activeTint",
		name = "Enabled",
		description = "Tint the whole screen when active.",
		section = sectionActiveTint,
		position = 1
	)
	default boolean activeTint()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		keyName = "activeTintColor",
		name = "Color",
		description = "Tint color.",
		section = sectionActiveTint,
		position = 2
	)
	default Color activeTintColor()
	{
		return new Color(0, 255, 0, 64);
	}
}

package com.afkbloodrchelper;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.Collections;
import java.util.List;
import java.util.function.Predicate;
import javax.inject.Inject;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.DecorativeObjectDespawned;
import net.runelite.api.events.DecorativeObjectSpawned;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GroundObjectDespawned;
import net.runelite.api.events.GroundObjectSpawned;
import net.runelite.api.events.WallObjectDespawned;
import net.runelite.api.events.WallObjectSpawned;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "AFK Blood RC Helper",
	description = "Contextual highlights, screen tint and a stage panel for blood runecrafting",
	tags = {"runecrafting", "rc", "blood", "afk", "skilling", "arceuus"}
)
public class AfkBloodRcHelperPlugin extends Plugin
{
	private static final String KEY_CRAFT_TRIP = "craftTrip";
	private static final String KEY_FIRST_BIND_DONE = "firstBindDone";
	private static final int ANIMATION_IDLE = -1;

	/**
	 * How long an inventory change counts as activity. Covers short gaps without an animation,
	 * e.g. the first chisel (no animation) before automatic chiseling of the rest starts.
	 */
	private static final long INVENTORY_ACTIVITY_MILLIS = 1200;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private AfkBloodRcHelperConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private Notifier notifier;

	@Inject
	private HighlightOverlay highlightOverlay;

	@Inject
	private InventoryHighlightOverlay inventoryHighlightOverlay;

	@Inject
	private TintOverlay tintOverlay;

	@Inject
	private InfoPanelOverlay infoPanelOverlay;

	@Inject
	private PathOverlay pathOverlay;

	@Inject
	private PathMinimapOverlay pathMinimapOverlay;

	// Tracked scene objects. These are tracked regardless of where the player is, so they
	// are already known when the player logs in (or loads a new scene) inside the area.
	private TileObject runestoneNorth;
	private TileObject runestoneSouth;
	private TileObject darkAltar;
	private TileObject bloodAltar;
	private TileObject shortcut69;
	private TileObject shortcut73Top;
	private TileObject shortcut73Bottom;

	@Getter(AccessLevel.PACKAGE)
	private boolean inArea;

	private boolean idle = true;

	/**
	 * Set right after venerating, binding or chiseling the last block so the next step is highlighted (and the idle
	 * tint shown) immediately, without waiting for the animation to end or the idle delay.
	 * Cleared once the player acts: moves, changes the inventory (chisel, bind, venerate), or the
	 * stage changes. Animations aren't used, since the previous action's animation is often still
	 * playing when the prompt appears.
	 */
	private boolean promptImmediately;

	/** True once a notification was sent for the current "action needed" stretch; reset when busy again. */
	private boolean notifiedForAction;
	private WorldPoint promptLocation;
	private InventoryState promptInventory;
	private Stage promptStage;

	private long lastActiveMillis;
	private volatile long lastInventoryChangeMillis;

	@Getter(AccessLevel.PACKAGE)
	private boolean levelUpOpen;

	@Getter(AccessLevel.PACKAGE)
	private Stage stage;

	@Getter(AccessLevel.PACKAGE)
	private Step step;

	@Getter(AccessLevel.PACKAGE)
	private Target target = Target.NONE;

	/**
	 * Walking path to the current target, recomputed every tick.
	 */
	@Getter(AccessLevel.PACKAGE)
	private List<WorldPoint> path = Collections.emptyList();
	private WorldPoint pathFrom;
	private Target pathTarget;

	/**
	 * Tiles to highlight for the Step Closer step (walkable or not): clicking any of them walks the
	 * player a short way to a tile within reach of the Blood Altar. Recomputed when the player moves.
	 */
	@Getter(AccessLevel.PACKAGE)
	private List<WorldPoint> stepCloserTiles = Collections.emptyList();
	private WorldPoint stepCloserFrom;

	@Getter(AccessLevel.PACKAGE)
	private InventoryState inventory;

	/**
	 * Inventory from the previous tick, used to detect venerating. Null right after
	 * logging in / hopping so that the (possibly not yet loaded) login inventory is
	 * never mistaken for a change made by the player.
	 */
	private InventoryState previousInventory;

	/**
	 * Which load of the loop the player is on. Persisted per account so it survives
	 * relogs and client restarts.
	 */
	private TripState tripState = new TripState();

	@Override
	protected void startUp()
	{
		overlayManager.add(tintOverlay);
		overlayManager.add(highlightOverlay);
		overlayManager.add(inventoryHighlightOverlay);
		overlayManager.add(infoPanelOverlay);
		overlayManager.add(pathOverlay);
		overlayManager.add(pathMinimapOverlay);

		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadTripState();
				scanScene();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(tintOverlay);
		overlayManager.remove(highlightOverlay);
		overlayManager.remove(inventoryHighlightOverlay);
		overlayManager.remove(infoPanelOverlay);
		overlayManager.remove(pathOverlay);
		overlayManager.remove(pathMinimapOverlay);
		clearObjects();
		resetSessionState();
	}

	@Provides
	AfkBloodRcHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AfkBloodRcHelperConfig.class);
	}

	// ------------------------------------------------------------------------------------
	// Session / login handling
	// ------------------------------------------------------------------------------------

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOADING:
				// The whole scene is reloaded; every object will spawn again afterwards.
				clearObjects();
				break;
			case LOGIN_SCREEN:
			case HOPPING:
			case CONNECTION_LOST:
				clearObjects();
				resetSessionState();
				break;
			case LOGGED_IN:
				loadTripState();
				break;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadTripState();
	}

	private void resetSessionState()
	{
		inArea = false;
		idle = true;
		stage = null;
		step = null;
		target = Target.NONE;
		inventory = null;
		previousInventory = null;
		clearPrompt();
		notifiedForAction = false;
		path = Collections.emptyList();
		stepCloserTiles = Collections.emptyList();
		stepCloserFrom = null;
		pathFrom = null;
		pathTarget = null;
	}

	private void loadTripState()
	{
		tripState = new TripState(readProfileFlag(KEY_CRAFT_TRIP), readProfileFlag(KEY_FIRST_BIND_DONE));
	}

	private boolean readProfileFlag(String key)
	{
		return Boolean.TRUE.equals(configManager.getRSProfileConfiguration(AfkBloodRcHelperConfig.GROUP, key, Boolean.class));
	}

	private void saveTripState(TripState before)
	{
		if (before.isCraftTrip() != tripState.isCraftTrip())
		{
			configManager.setRSProfileConfiguration(AfkBloodRcHelperConfig.GROUP, KEY_CRAFT_TRIP, tripState.isCraftTrip());
		}
		if (before.isFirstBindDone() != tripState.isFirstBindDone())
		{
			configManager.setRSProfileConfiguration(AfkBloodRcHelperConfig.GROUP, KEY_FIRST_BIND_DONE, tripState.isFirstBindDone());
		}
	}

	boolean isCraftTrip()
	{
		return tripState.isCraftTrip();
	}

	// ------------------------------------------------------------------------------------
	// Object tracking
	// ------------------------------------------------------------------------------------

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		onTileObject(null, event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		onTileObject(event.getGameObject(), null);
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		onTileObject(null, event.getGroundObject());
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		onTileObject(event.getGroundObject(), null);
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		onTileObject(null, event.getWallObject());
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		onTileObject(event.getWallObject(), null);
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		onTileObject(null, event.getDecorativeObject());
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		onTileObject(event.getDecorativeObject(), null);
	}

	private void onTileObject(TileObject oldObject, TileObject newObject)
	{
		TileObject object = newObject != null ? newObject : oldObject;
		if (object == null)
		{
			return;
		}

		switch (object.getId())
		{
			case BloodRcIds.RUNESTONE_NORTH:
				runestoneNorth = replace(runestoneNorth, oldObject, newObject);
				break;
			case BloodRcIds.RUNESTONE_SOUTH:
				runestoneSouth = replace(runestoneSouth, oldObject, newObject);
				break;
			case BloodRcIds.DARK_ALTAR:
				darkAltar = replace(darkAltar, oldObject, newObject);
				break;
			case BloodRcIds.BLOOD_ALTAR:
				bloodAltar = replace(bloodAltar, oldObject, newObject);
				break;
			case BloodRcIds.SHORTCUT_69:
				shortcut69 = replace(shortcut69, oldObject, newObject);
				break;
			case BloodRcIds.SHORTCUT_73_TOP:
				shortcut73Top = replace(shortcut73Top, oldObject, newObject);
				break;
			case BloodRcIds.SHORTCUT_73_BOTTOM:
				shortcut73Bottom = replace(shortcut73Bottom, oldObject, newObject);
				break;
		}
	}

	/**
	 * Only clear a tracked object when the despawning object is the one being tracked.
	 */
	private static TileObject replace(TileObject current, TileObject oldObject, TileObject newObject)
	{
		if (newObject != null)
		{
			return newObject;
		}
		return current == oldObject ? null : current;
	}

	private void clearObjects()
	{
		runestoneNorth = null;
		runestoneSouth = null;
		darkAltar = null;
		bloodAltar = null;
		shortcut69 = null;
		shortcut73Top = null;
		shortcut73Bottom = null;
	}

	/**
	 * Spawn events are not fired for objects that already exist when the plugin is turned
	 * on while logged in, so look for them in the loaded scene.
	 */
	private void scanScene()
	{
		Scene scene = client.getTopLevelWorldView().getScene();
		Tile[][][] tiles = scene.getTiles();
		int plane = client.getTopLevelWorldView().getPlane();
		if (tiles == null || plane < 0 || plane >= tiles.length)
		{
			return;
		}

		for (Tile[] column : tiles[plane])
		{
			for (Tile tile : column)
			{
				if (tile == null)
				{
					continue;
				}
				GameObject[] gameObjects = tile.getGameObjects();
				if (gameObjects != null)
				{
					for (GameObject gameObject : gameObjects)
					{
						if (gameObject != null)
						{
							onTileObject(null, gameObject);
						}
					}
				}
				if (tile.getGroundObject() != null)
				{
					onTileObject(null, tile.getGroundObject());
				}
				if (tile.getWallObject() != null)
				{
					onTileObject(null, tile.getWallObject());
				}
				if (tile.getDecorativeObject() != null)
				{
					onTileObject(null, tile.getDecorativeObject());
				}
			}
		}
	}

	// ------------------------------------------------------------------------------------
	// Idle detection
	// ------------------------------------------------------------------------------------

	@Subscribe
	public void onClientTick(ClientTick tick)
	{
		Player player = client.getLocalPlayer();
		if (!inArea || player == null)
		{
			return;
		}

		long now = System.currentTimeMillis();
		boolean active = player.getAnimation() != ANIMATION_IDLE
			|| player.getPoseAnimation() != player.getIdlePoseAnimation()
			|| now - lastInventoryChangeMillis < INVENTORY_ACTIVITY_MILLIS;

		if (active)
		{
			lastActiveMillis = now;
			idle = false;
		}
		else
		{
			idle = now - lastActiveMillis >= config.idleDelay();
		}
	}

	// ------------------------------------------------------------------------------------
	// Stage logic
	// ------------------------------------------------------------------------------------

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}

		WorldPoint location = player.getWorldLocation();
		inArea = BloodRcIds.REGIONS.contains(location.getRegionID());
		if (!inArea)
		{
			stage = null;
			step = null;
			target = Target.NONE;
			previousInventory = null;
			path = Collections.emptyList();
			return;
		}

		levelUpOpen = client.getWidget(InterfaceID.LevelupDisplay.UNIVERSE) != null;

		ItemContainer container = client.getItemContainer(InventoryID.INV);
		if (container == null)
		{
			// Inventory not loaded yet (e.g. right after logging in). Don't guess.
			stage = null;
			step = null;
			target = Target.NONE;
			return;
		}

		InventoryState current = InventoryState.read(container);
		boolean inventoryChanged = previousInventory != null && !current.equals(previousInventory);
		if (inventoryChanged)
		{
			lastInventoryChangeMillis = System.currentTimeMillis();
		}
		// Venerating, binding or running out of blocks to chisel: show the next step right away.
		boolean promptNow = TripState.venerated(previousInventory, current)
			|| TripState.bound(previousInventory, current)
			|| TripState.finishedChiseling(previousInventory, current);
		TripState before = new TripState(tripState.isCraftTrip(), tripState.isFirstBindDone());
		tripState.update(previousInventory, current);
		saveTripState(before);
		previousInventory = current;
		inventory = current;

		decideNextAction(location, current, promptNow);

		notifyIfActionNeeded();
		updateStepCloserTiles(location);
		if (config.pathDisplay() == PathDisplay.OFF)
		{
			path = Collections.emptyList();
			pathFrom = null;
		}
		else if (!location.equals(pathFrom) || !target.equals(pathTarget))
		{
			// Only re-path when the player or the destination changed.
			path = findPath(location);
			pathFrom = location;
			pathTarget = target;
		}
	}

	private void decideNextAction(WorldPoint location, InventoryState inv, boolean promptNow)
	{
		stage = tripState.stage(inv);
		routeStage(location, inv);

		if (promptNow)
		{
			// Don't wait for the venerate/bind animation to finish or the idle delay.
			promptImmediately = true;
			promptLocation = location;
			promptInventory = inv;
			promptStage = stage;
		}
		else if (promptImmediately
			&& (stage != promptStage || !location.equals(promptLocation) || !inv.equals(promptInventory)))
		{
			clearPrompt();
		}

		boolean runEnabled = client.getVarpValue(VarPlayerID.OPTION_RUN) == 1;
		if (config.suggestRun() && !runEnabled && client.getEnergy() > 50 * 100
			&& client.getWidget(InterfaceID.Orbs.RUNBUTTON) != null)
		{
			step = Step.ENABLE_RUN;
			target = Target.RUN_ORB;
		}
		else if (config.remindBloodEssence() && inv.getInactiveEssence() > 0 && inv.getActiveEssence() == 0)
		{
			step = Step.ACTIVATE_ESSENCE;
			target = Target.item(BloodRcIds.BLOOD_ESSENCE_INACTIVE);
		}
	}

	private void routeStage(WorldPoint location, InventoryState inv)
	{
		boolean inBasin = BloodRcIds.inMineBasin(location);
		switch (stage)
		{
			case MINE:
				if (inBasin)
				{
					TileObject runestone = chooseRunestone(location);
					step = runestone == null ? Step.RUNESTONES_DEPLETED : Step.MINE_RUNESTONE;
					target = Target.object(runestone, null);
				}
				else if (BloodRcIds.onBloodAltarSide(location))
				{
					step = Step.CLIMB_TO_MINE_FROM_BLOOD;
					target = Target.object(shortcut73(), null);
				}
				else
				{
					step = Step.CLIMB_TO_MINE_FROM_DARK;
					target = Target.object(shortcut69, BloodRcIds.WALK_DARK_TO_ROCKS);
				}
				break;
			case VENERATE:
				if (inBasin)
				{
					step = Step.CLIMB_TO_DARK_ALTAR;
					target = Target.object(shortcut69, null);
				}
				else
				{
					step = Step.VENERATE;
					target = Target.object(darkAltar, null);
				}
				break;
			case CHISEL:
				step = Step.CHISEL;
				target = Target.item(nextChiselItem());
				break;
			case BIND:
				if (inBasin)
				{
					step = Step.CLIMB_TO_BLOOD_ALTAR;
					target = Target.object(shortcut73(), null);
				}
				else
				{
					routeToBloodAltar(location);
				}
				break;
		}
	}

	private void routeToBloodAltar(WorldPoint location)
	{
		boolean inReach = BloodRcIds.distanceToBloodAltar(location) <= BloodRcIds.BLOOD_ALTAR_REACH;
		if (bloodAltar != null && inReach)
		{
			// Close enough to click: the altar flashes as soon as it's on screen.
			step = Step.BIND;
			target = Target.object(bloodAltar, isNorthOf(location, BloodRcIds.WALK_DARK_TO_BLOOD) ? BloodRcIds.WALK_DARK_TO_BLOOD : null);
		}
		else if (config.stepCloserToBloodAltar() && bloodAltar != null
			&& location.distanceTo(BloodRcIds.DARK_APPROACH) <= 8)
		{
			// Altar is loaded but just out of reach from the Dark Altar: a few steps south fixes that.
			step = Step.STEP_CLOSER;
			target = Target.object(null, BloodRcIds.STEP_CLOSER_TO_BLOOD);
		}
		else
		{
			// Out of reach (clicking it wouldn't work) or not loaded: walk.
			step = Step.WALK_TO_BLOOD_ALTAR;
			target = Target.object(null, BloodRcIds.WALK_DARK_TO_BLOOD);
		}
	}

	private void notifyIfActionNeeded()
	{
		boolean actionNeeded = step != null && target != Target.NONE && isIdle() && !levelUpOpen;
		if (!actionNeeded)
		{
			notifiedForAction = false;
			return;
		}
		if (!notifiedForAction)
		{
			notifiedForAction = true;
			if (config.notifyAction().isEnabled())
			{
				notifier.notify(config.notifyAction(), "Blood RC: " + step.getText());
			}
		}
	}

	private void updateStepCloserTiles(WorldPoint location)
	{
		if (step != Step.STEP_CLOSER)
		{
			stepCloserTiles = Collections.emptyList();
			stepCloserFrom = null;
			return;
		}
		if (location.equals(stepCloserFrom))
		{
			return;
		}
		stepCloserFrom = location;

		Pathfinder.DistanceMap map = Pathfinder.distances(client.getTopLevelWorldView(), location);
		List<WorldPoint> tiles = new java.util.ArrayList<>();
		for (WorldPoint candidate : BloodRcIds.STEP_CLOSER_CANDIDATES.toWorldPointList())
		{
			WorldPoint destination = Pathfinder.clickDestination(map, candidate);
			if (destination != null
				&& BloodRcIds.distanceToBloodAltar(destination) <= BloodRcIds.BLOOD_ALTAR_REACH
				&& map.get(destination) <= BloodRcIds.STEP_CLOSER_MAX_WALK)
			{
				tiles.add(candidate);
			}
		}

		// To be safe, leave out the southmost row of what would be shown.
		int southmost = tiles.stream().mapToInt(WorldPoint::getY).min().orElse(Integer.MIN_VALUE);
		tiles.removeIf(p -> p.getY() == southmost);
		stepCloserTiles = tiles;
	}

	// ------------------------------------------------------------------------------------
	// Path
	// ------------------------------------------------------------------------------------

	private List<WorldPoint> findPath(WorldPoint location)
	{
		TileObject object = target.getObject();
		WorldArea area = target.getFallbackArea();
		if (object == null && area == null)
		{
			return Collections.emptyList();
		}

		if (object != null)
		{
			List<WorldPoint> toObject = Pathfinder.find(client.getTopLevelWorldView(), location, nextTo(object));
			if (!toObject.isEmpty())
			{
				return toObject;
			}
		}
		if (area != null)
		{
			List<WorldPoint> toArea = Pathfinder.find(client.getTopLevelWorldView(), location, area::contains);
			if (!toArea.isEmpty())
			{
				return toArea;
			}
		}
		if (step == Step.WALK_TO_BLOOD_ALTAR)
		{
			// The walk loops west around the ridge and can leave the loaded scene; use the
			// recorded route from the nearest waypoint onwards.
			return recordedBloodApproach(location);
		}
		return Collections.emptyList();
	}

	/**
	 * Goal: any tile next to (but not on) the object's footprint.
	 */
	private Predicate<WorldPoint> nextTo(TileObject object)
	{
		int minX, minY, maxX, maxY;
		int baseX = client.getTopLevelWorldView().getBaseX();
		int baseY = client.getTopLevelWorldView().getBaseY();
		if (object instanceof GameObject)
		{
			GameObject gameObject = (GameObject) object;
			minX = baseX + gameObject.getSceneMinLocation().getX();
			minY = baseY + gameObject.getSceneMinLocation().getY();
			maxX = baseX + gameObject.getSceneMaxLocation().getX();
			maxY = baseY + gameObject.getSceneMaxLocation().getY();
		}
		else
		{
			WorldPoint p = object.getWorldLocation();
			minX = maxX = p.getX();
			minY = maxY = p.getY();
		}
		final int x1 = minX, y1 = minY, x2 = maxX, y2 = maxY;
		return p ->
		{
			boolean inside = p.getX() >= x1 && p.getX() <= x2 && p.getY() >= y1 && p.getY() <= y2;
			return !inside && p.getX() >= x1 - 1 && p.getX() <= x2 + 1 && p.getY() >= y1 - 1 && p.getY() <= y2 + 1;
		};
	}

	private static List<WorldPoint> recordedBloodApproach(WorldPoint location)
	{
		List<WorldPoint> route = BloodRcIds.BLOOD_APPROACH;
		int nearest = 0;
		for (int i = 1; i < route.size(); i++)
		{
			if (location.distanceTo(route.get(i)) < location.distanceTo(route.get(nearest)))
			{
				nearest = i;
			}
		}
		List<WorldPoint> path = new java.util.ArrayList<>();
		path.add(location);
		path.addAll(route.subList(nearest, route.size()));
		return path;
	}

	private static boolean isNorthOf(WorldPoint location, WorldArea area)
	{
		return location.getY() >= area.getY() + area.getHeight();
	}

	private void clearPrompt()
	{
		promptImmediately = false;
		promptLocation = null;
		promptInventory = null;
		promptStage = null;
	}

	boolean isIdle()
	{
		return idle || promptImmediately;
	}

	private TileObject shortcut73()
	{
		return shortcut73Top != null ? shortcut73Top : shortcut73Bottom;
	}

	private TileObject chooseRunestone(WorldPoint location)
	{
		boolean northDense = runestoneNorth != null && client.getVarbitValue(BloodRcIds.VARBIT_RUNESTONE_NORTH) == 0;
		boolean southDense = runestoneSouth != null && client.getVarbitValue(BloodRcIds.VARBIT_RUNESTONE_SOUTH) == 0;

		if (northDense && southDense)
		{
			int north = location.distanceTo(runestoneNorth.getWorldLocation());
			int south = location.distanceTo(runestoneSouth.getWorldLocation());
			return north <= south ? runestoneNorth : runestoneSouth;
		}
		if (northDense)
		{
			return runestoneNorth;
		}
		if (southDense)
		{
			return runestoneSouth;
		}
		return null;
	}

	private int nextChiselItem()
	{
		if (client.isWidgetSelected())
		{
			Widget selected = client.getSelectedWidget();
			if (selected != null && selected.getItemId() == BloodRcIds.CHISEL)
			{
				return BloodRcIds.DARK_ESSENCE_BLOCK;
			}
		}
		return BloodRcIds.CHISEL;
	}

	// ------------------------------------------------------------------------------------
	// Colors
	// ------------------------------------------------------------------------------------

	Color currentHighlightColor()
	{
		return flash(config.actionFlash(), config.actionColor(), config.actionColor2(),
			config.actionColor1Time(), config.actionColor2Time());
	}

	Color currentIdleTintColor()
	{
		return flash(config.idleTintFlash(), config.idleTintColor(), config.idleTintColor2(),
			config.idleTintColor1Time(), config.idleTintColor2Time());
	}

	private static Color flash(boolean enabled, Color color1, Color color2, int time1, int time2)
	{
		if (enabled)
		{
			long cycle = Math.max(1, (long) time1 + time2);
			if (System.currentTimeMillis() % cycle >= time1)
			{
				return color2;
			}
		}
		return color1;
	}
}

package com.afkbloodrchelper;

import com.google.common.collect.ImmutableList;
import com.google.common.collect.ImmutableSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;

/**
 * IDs and locations used by the plugin.
 */
final class BloodRcIds
{
	private BloodRcIds()
	{
	}

	// Items
	static final int DENSE_ESSENCE_BLOCK = ItemID.ARCEUUS_ESSENCE_BLOCK;
	static final int DARK_ESSENCE_BLOCK = ItemID.ARCEUUS_ESSENCE_BLOCK_DARK;
	static final int DARK_ESSENCE_FRAGMENTS = 7938; // gameval name: BIGBLANKRUNE
	static final int CHISEL = ItemID.CHISEL;
	static final int BLOOD_ESSENCE_INACTIVE = ItemID.BLOOD_ESSENCE_INACTIVE;
	static final int BLOOD_ESSENCE_ACTIVE = ItemID.BLOOD_ESSENCE_ACTIVE;
	static final int BLOOD_RUNE = ItemID.BLOODRUNE;

	// Objects
	static final int RUNESTONE_NORTH = ObjectID.ARCEUUS_RUNESTONE_BASE_1;
	static final int RUNESTONE_SOUTH = ObjectID.ARCEUUS_RUNESTONE_BASE_2;
	static final int DARK_ALTAR = ObjectID.ARCHEUS_ALTAR_DARK;
	static final int BLOOD_ALTAR = ObjectID.ARCHEUS_ALTAR_BLOOD;
	static final int SHORTCUT_69 = 34741; // Rocks north of the runestones (to/from the Dark Altar)
	static final int SHORTCUT_73_TOP = ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_GREY_TOP; // Rocks west of the runestones
	static final int SHORTCUT_73_BOTTOM = ObjectID.ARCHEUUS_RUNESTONE_SHORTCUT_GREY_BOTTOM;

	// Varbits: 0 = dense (mineable), otherwise depleted
	static final int VARBIT_RUNESTONE_NORTH = VarbitID.ARCEUUS_RUNESTONE_1;
	static final int VARBIT_RUNESTONE_SOUTH = VarbitID.ARCEUUS_RUNESTONE_2;

	// Map regions making up the blood runecrafting area (runestones, Dark Altar, Blood Altar and the paths between)
	static final Set<Integer> REGIONS = ImmutableSet.of(6460, 6715, 6716, 6971, 6972);

	// Walk-to tiles used when the next object is not clickable on screen
	static final WorldArea WALK_DARK_TO_ROCKS = new WorldArea(1751, 3873, 5, 5, 0);
	static final WorldArea WALK_DARK_TO_BLOOD = new WorldArea(1720, 3854, 5, 5, 0);

	// Locations below are from Jam's Arceuus Runecrafting (JamsRepos/zeah-rc-helper, BSD 2-Clause),
	// captured in game by its author.

	/**
	 * Four tiles south of the Dark Altar: the nearest spot to it from which the Blood Altar can be clicked.
	 */
	static final WorldPoint DARK_APPROACH = new WorldPoint(1718, 3878, 0);

	/**
	 * "Step Closer to Blood Altar" tiles: a block around {@link #DARK_APPROACH}, every tile of which
	 * is still within reach of the Blood Altar (y <= 3878), so there is more to click when zoomed out.
	 * Only walkable tiles are highlighted.
	 */
	static final WorldArea STEP_CLOSER_TO_BLOOD = new WorldArea(1715, 3876, 7, 3, 0);

	/**
	 * Extra click tiles for "Step Closer": tiles around and south of {@link #STEP_CLOSER_TO_BLOOD}
	 * (mostly the unwalkable ridge) are also highlighted when clicking them would make the player
	 * walk a short way to a tile within reach of the Blood Altar.
	 */
	static final WorldArea STEP_CLOSER_CANDIDATES = new WorldArea(1711, 3866, 15, 13, 0);
	static final int STEP_CLOSER_MAX_WALK = 12;

	/** Blood Altar 4x4 footprint (south-west tile) and the furthest distance it can be clicked from. */
	static final int BLOOD_ALTAR_SW_X = 1716;
	static final int BLOOD_ALTAR_SW_Y = 3829;
	static final int BLOOD_ALTAR_SIZE = 4;
	static final int BLOOD_ALTAR_REACH = 46;

	/** Dark Altar to Blood Altar walking route (west around the ridge, then south-east). */
	static final List<WorldPoint> BLOOD_APPROACH = ImmutableList.of(
		new WorldPoint(1701, 3880, 0),
		new WorldPoint(1674, 3879, 0),
		new WorldPoint(1659, 3881, 0),
		new WorldPoint(1661, 3863, 0),
		new WorldPoint(1675, 3859, 0),
		new WorldPoint(1731, 3856, 0),
		new WorldPoint(1735, 3849, 0),
		new WorldPoint(1735, 3828, 0),
		new WorldPoint(1728, 3826, 0),
		new WorldPoint(1717, 3826, 0)
	);

	/**
	 * Chebyshev distance from a tile to the nearest tile of the Blood Altar.
	 */
	static int distanceToBloodAltar(WorldPoint p)
	{
		int max = BLOOD_ALTAR_SIZE - 1;
		int dx = Math.max(Math.max(BLOOD_ALTAR_SW_X - p.getX(), p.getX() - (BLOOD_ALTAR_SW_X + max)), 0);
		int dy = Math.max(Math.max(BLOOD_ALTAR_SW_Y - p.getY(), p.getY() - (BLOOD_ALTAR_SW_Y + max)), 0);
		return Math.max(dx, dy);
	}


	/**
	 * The runestone basin: east of the 73 shortcut (x 1742) and south of the 69 shortcut (y 3873).
	 */
	static boolean inMineBasin(WorldPoint p)
	{
		return p.getX() >= 1743 && p.getX() <= 1790 && p.getY() >= 3830 && p.getY() <= 3872;
	}

	/**
	 * West of the runestones on the Blood Altar side of the 73 shortcut (as opposed to up by the Dark Altar).
	 */
	static boolean onBloodAltarSide(WorldPoint p)
	{
		return p.getX() < 1743 && p.getY() < 3866;
	}
}

package com.afkbloodrchelper;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Flashes the next object to click (or walk-to tiles when it isn't clickable) and the run orb.
 * Drawn on top of everything, above the screen tint.
 */
class HighlightOverlay extends Overlay
{
	private final Client client;
	private final AfkBloodRcHelperPlugin plugin;
	private final AfkBloodRcHelperConfig config;

	@Inject
	private HighlightOverlay(Client client, AfkBloodRcHelperPlugin plugin, AfkBloodRcHelperConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		// Dynamic overlays render in ascending priority, so this draws after the (low priority) tint.
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isInArea() || !config.actionEnabled())
		{
			return null;
		}
		if (config.actionOnlyWhenIdle() && !plugin.isIdle())
		{
			return null;
		}

		Target target = plugin.getTarget();
		Color color = plugin.currentHighlightColor();

		if (target.isRunOrb())
		{
			Widget runOrb = client.getWidget(InterfaceID.Orbs.RUNBUTTON);
			if (runOrb != null && !runOrb.isHidden())
			{
				OverlayUtil.renderPolygon(graphics, runOrb.getBounds(), color, color, new BasicStroke());
			}
			return null;
		}

		TileObject object = target.getObject();
		Shape clickbox = object != null ? object.getClickbox() : null;
		if (clickbox != null && isOnScreen(clickbox))
		{
			OverlayUtil.renderHoverableArea(graphics, clickbox, client.getMouseCanvasPosition(), color, color, color);
		}
		else if (target.getFallbackArea() != null)
		{
			List<WorldPoint> stepCloserTiles = plugin.getStepCloserTiles();
			if (target.getFallbackArea() == BloodRcIds.STEP_CLOSER_TO_BLOOD && !stepCloserTiles.isEmpty())
			{
				// Step Closer: every nearby tile (walkable or not) that walks the player into reach.
				for (WorldPoint point : stepCloserTiles)
				{
					highlightTile(graphics, point, color);
				}
			}
			else
			{
				highlightTiles(graphics, target.getFallbackArea(), color);
			}
		}
		return null;
	}

	/**
	 * An object counts as clickable when some part of its clickbox is inside the game viewport.
	 */
	private boolean isOnScreen(Shape clickbox)
	{
		Rectangle viewport = new Rectangle(
			client.getViewportXOffset(), client.getViewportYOffset(),
			client.getViewportWidth(), client.getViewportHeight());
		if (!clickbox.getBounds().intersects(viewport))
		{
			return false;
		}
		Area visible = new Area(clickbox);
		visible.intersect(new Area(viewport));
		return !visible.isEmpty();
	}

	private void highlightTiles(Graphics2D graphics, WorldArea area, Color color)
	{
		for (WorldPoint point : area.toWorldPointList())
		{
			if (Pathfinder.isWalkable(client.getTopLevelWorldView(), point))
			{
				highlightTile(graphics, point, color);
			}
		}
	}

	private void highlightTile(Graphics2D graphics, WorldPoint point, Color color)
	{
		LocalPoint local = LocalPoint.fromWorld(client.getTopLevelWorldView(), point);
		if (local == null)
		{
			return;
		}
		Polygon poly = Perspective.getCanvasTilePoly(client, local);
		if (poly != null)
		{
			OverlayUtil.renderPolygon(graphics, poly, color, color, new BasicStroke(1));
		}
	}
}

package com.afkbloodrchelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Info panel with the current blood runecrafting stage.
 */
class InfoPanelOverlay extends OverlayPanel
{
	private static final Color TITLE_COLOR = new Color(70, 140, 255);

	private final AfkBloodRcHelperPlugin plugin;
	private final AfkBloodRcHelperConfig config;

	@Inject
	private InfoPanelOverlay(AfkBloodRcHelperPlugin plugin, AfkBloodRcHelperConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.TOP_LEFT);
		// Same layer as the full-screen tint. Within a layer, DYNAMIC overlays (the tint and
		// highlights) render before positioned ones, so the panel draws on top of the tint.
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(PRIORITY_MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isInArea() || !config.showInfoPanel())
		{
			return null;
		}
		buildPanel();
		return super.render(graphics);
	}

	private void buildPanel()
	{
		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Blood Runecrafting")
			.color(TITLE_COLOR)
			.build());

		Stage stage = plugin.getStage();
		InventoryState inv = plugin.getInventory();
		if (stage == null || inv == null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Waiting for inventory...")
				.build());
			return;
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Stage:")
			.right(stage.getLabel())
			.rightColor(stage.getColor())
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Load:")
			.right(loadText(stage, inv))
			.build());

		// The fragment stack always reports quantity 1 (the real count isn't in the item), so
		// only show whether any are carried.
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Fragments:")
			.right(inv.getFragments() > 0 ? "Carrying" : "None")
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Status:")
			.right(plugin.isIdle() ? "Idle" : "Active")
			.rightColor(plugin.isIdle() ? Color.ORANGE : Color.GREEN)
			.build());

		Step step = plugin.getStep();
		if (step != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(step.getText())
				.leftColor(Color.YELLOW)
				.build());
		}
	}

	/**
	 * Load 1 is chiseled into fragments at the Dark Altar, load 2 is taken to the Blood Altar.
	 */
	private String loadText(Stage stage, InventoryState inv)
	{
		boolean secondLoad;
		switch (stage)
		{
			case MINE:
			case VENERATE:
				secondLoad = inv.getFragments() > 0;
				break;
			case BIND:
				secondLoad = true;
				break;
			default:
				secondLoad = plugin.isCraftTrip();
				break;
		}
		return secondLoad ? "2 / 2 (craft)" : "1 / 2 (fragments)";
	}
}

