import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the walking path to the next destination on the minimap.
 */
class PathMinimapOverlay extends Overlay
{
	private final Client client;
	private final AfkBloodRcHelperPlugin plugin;
	private final AfkBloodRcHelperConfig config;

	@Inject
	private PathMinimapOverlay(Client client, AfkBloodRcHelperPlugin plugin, AfkBloodRcHelperConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<WorldPoint> path = plugin.getPath();
		if (!plugin.isInArea() || !config.pathDisplay().minimap() || path.size() < 2)
		{
			return null;
		}

		WorldView worldView = client.getTopLevelWorldView();
		graphics.setColor(config.pathColor());
		graphics.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

		Point previous = null;
		for (WorldPoint point : path)
		{
			LocalPoint local = LocalPoint.fromWorld(worldView, point);
			Point current = local == null ? null : Perspective.localToMinimap(client, local);
			if (previous != null && current != null)
			{
				graphics.drawLine(previous.getX(), previous.getY(), current.getX(), current.getY());
			}
			previous = current;
		}
		return null;
	}
}

